#!/bin/bash
# ============================================================
# UI: up_header
# DESCRIPTION: print header for up command
# ============================================================

# up_header function
up_header() {
  local user
  local hours
  local greeting

  hours=$(date +%H)
  user=$(whoami | tr '[:lower:]' '[:upper:]')

  case "$hours" in
    0[5-9]|1[0-1]) greeting="GOOD MORNING"   ;; # 05:00 - 11:59
    1[2-7])        greeting="GOOD AFTERNOON" ;; # 12:00 - 17:59
    *)             greeting="GOOD EVENING"   ;; # 18:00 - 04:59
  esac

  printf "%b ═════════════════════════════════════════════════════════════════════════\n" "${COLOR_BLUE}"
  printf "%b%b   %s, %s!%b\n" "${COLOR_YELLOW}" "${C_BOLD}" "$greeting" "$user" "${COLOR_BLUE}"
  printf " ═════════════════════════════════════════════════════════════════════════\n"
  printf "                                                                       \n"
  printf "    ██████╗ ███████╗██╗   ██╗███████╗████████╗ █████╗  ██████╗██╗  ██╗\n"
  printf "    ██╔══██╗██╔════╝██║   ██║██╔════╝╚══██╔══╝██╔══██╗██╔════╝██║ ██╔╝\n"
  printf "    ██║  ██║█████╗  ██║   ██║███████╗   ██║   ███████║██║     █████═╝ \n"
  printf "    ██║  ██║██╔══╝  ╚██╗ ██╔╝╚════██║   ██║   ██╔══██║██║     ██╔═██╗ \n"
  printf "    ██████╔╝███████╗ ╚████╔╝ ███████║   ██║   ██║  ██║╚██████╗██║  ██╗\n"
  printf "    ╚═════╝ ╚══════╝  ╚═══╝  ╚══════╝   ╚═╝   ╚═╝  ╚═╝ ╚═════╝╚═╝  ╚═╝\n"
  printf "                                                                       \n"
  printf " ════════════════════════════════════════════════════════════════════════%b\n" "${C_NC}"
  printf "\n"
}